<template><section class="module-page module-composed-page"><header class="module-heading"><div><h1>资源管理</h1><p>统一查看课程中的电子书、视频、PPT 和压缩包资源。</p></div><el-button type="primary" icon="el-icon-reading" @click="$router.push('/management/courses')">进入课程管理</el-button></header><div class="module-table-wrap"><el-table v-loading="loading" :data="rows" empty-text="暂无资源"><el-table-column prop="name" label="资源名称" min-width="220" /><el-table-column prop="resourceType" label="类型" width="120" /><el-table-column prop="courseName" label="所属课程" min-width="180" /><el-table-column label="状态" width="100"><template slot-scope="s"><el-tag size="small" :type="s.row.enabled ? 'success' : 'info'">{{ s.row.enabled ? '启用' : '停用' }}</el-tag></template></el-table-column></el-table></div></section></template>
<script>
import { listAdminCourses } from '@/api/Courses'
export default { data: () => ({ loading: false, rows: [] }), async created () { this.loading = true; try { const r = await listAdminCourses(); this.rows = (r.data || []).reduce((all, item) => all.concat((item.resources || []).map(resource => Object.assign({}, resource, { courseName: item.course.name }))), []) } finally { this.loading = false } } }
</script>
